        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint unlockTimeParam, uint withdrawAmount, uint deposit) public payable {
        require(address(this).balance >= deposit);

        // Deposit the caller's funds (the amount to potentially withdraw from).
        c.Put{value: deposit}(unlockTimeParam);

        (, uint balBefore) = c.Acc(address(this));
        uint etherBefore = address(c).balance;

        bool reverted;
        try c.Collect(withdrawAmount) { reverted = false; }
        catch { reverted = true; }

        (, uint balAfter) = c.Acc(address(this));
        uint etherAfter = address(c).balance;

        // Conservation rule: whatever Collect does (revert, silent no-op, or a
        // successful withdrawal), the recorded balance can never increase, and
        // the drop in recorded balance must exactly equal the drop in the
        // contract's actual ether balance. A faulty version that steals ether,
        // credits the caller without debiting the record (or vice versa), or
        // increases balances would break this.
        assert(
            balAfter <= balBefore &&
            (balBefore - balAfter) == (etherBefore - etherAfter)
        );
    }

    receive() external payable {}
}

